  if(result.owned){if(task)session.home.leave();session.home.resetPose();const q=t.position;session.pet.root.position.set(q.x,session.town.nav().ground(q.x,q.z)+.001,q.z);session.pet.root.rotation.y=t.heading;const m=session.boundPlace!==t.place||!session.pet.motion?session.pet.bind({ground:session.town.nav().ground,matchSpeed:true}):session.pet.motion;session.boundPlace=t.place;m.setActionPose(result.speed?{}:idlePose('look',t.time));session.pet.setMood(moodFromCare(session.care.state));m.update(dt,result.speed,0,result.speed>0);session.care.tick(dt);}
